"""daemon.py — 数字员工工位运行时守护进程管理。

用法：
  daemon.py <agent_id>              前台运行（生产环境由 systemd company-agent@
                                    模板服务管理，本脚本不重复 fork）
  daemon.py <agent_id> --init       初始化运行时目录结构
  daemon.py <agent_id> --status     查看 PID / Token 预算 / 技能数
  daemon.py <agent_id> --stop       停止运行中的工位进程

仅使用 Python3 标准库 + agent_runtime 包。
"""
import argparse
import json
import os
import signal
import sys
import time
from pathlib import Path

from agent_runtime.core.config import RuntimeConfig


def _read_pid(config):
    try:
        return int(config.pid_file.read_text(encoding='utf-8').strip())
    except (ValueError, OSError):
        return None


def _pid_alive(pid):
    if not pid:
        return False
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False


def cmd_init(config):
    config.ensure_dirs()
    print('运行时目录已初始化: %s' % config.runtime_home)
    return 0


def cmd_status(config):
    pid = _read_pid(config)
    alive = _pid_alive(pid)
    print('agent_id    : %s' % config.agent_id)
    print('runtime_home: %s' % config.runtime_home)
    print('pid         : %s (%s)' % (
        pid if pid else '-', 'running' if alive else 'not running'))
    print('port        : %s' % config.port)
    # Token 预算状态（从 SQLite 读取）
    try:
        from agent_runtime.core.db import Database
        db = Database(config.db_file)
        meter = db.get_token_meter(time.strftime('%Y-%m'))
        if meter:
            print('token       : %s/%s (month=%s)' % (
                meter.get('used', 0),
                meter.get('cap', config.get('token_monthly_cap')),
                meter.get('month', '?')))
        else:
            print('token       : 无计量记录')
        db.close()
    except Exception:
        print('token       : 无计量记录')
    # 技能数
    builtin = [d for d in Path(config.skills_builtin_dir).iterdir()
               if d.is_dir() and (d / 'manifest.json').exists()] \
        if Path(config.skills_builtin_dir).exists() else []
    user = [d for d in Path(config.skills_user_dir).iterdir()
            if d.is_dir() and (d / 'manifest.json').exists()] \
        if config.skills_user_dir.exists() else []
    print('skills      : builtin=%d user=%d' % (len(builtin), len(user)))
    return 0


def cmd_stop(config):
    pid = _read_pid(config)
    if not _pid_alive(pid):
        print('工位进程未运行')
        try:
            config.pid_file.unlink()
        except OSError:
            pass
        return 0
    os.kill(pid, signal.SIGTERM)
    for _ in range(20):
        if not _pid_alive(pid):
            print('工位进程 %d 已停止' % pid)
            return 0
        time.sleep(0.5)
    print('警告: 进程 %d 未在 10s 内退出' % pid)
    return 1


def cmd_run(config):
    """前台运行：写 PID 文件 + 信号处理后进入 WebSocket 主循环。"""
    pid = _read_pid(config)
    if _pid_alive(pid):
        print('错误: 工位已在运行（pid=%d）' % pid)
        return 1
    config.ensure_dirs()
    config.pid_file.write_text(str(os.getpid()), encoding='utf-8')

    # 延迟导入，避免 --status 等命令触发完整组件加载
    from agent_runtime.main import main as runtime_main

    def _on_signal(signum, _frame):
        print('\n收到信号 %d，正在退出...' % signum)
        try:
            config.pid_file.unlink()
        except OSError:
            pass
        raise SystemExit(0)

    signal.signal(signal.SIGTERM, _on_signal)
    signal.signal(signal.SIGINT, _on_signal)
    try:
        return runtime_main() or 0
    finally:
        try:
            config.pid_file.unlink()
        except OSError:
            pass


def main():
    parser = argparse.ArgumentParser(description='数字员工工位守护进程管理')
    parser.add_argument('agent_id', help='员工 ID（如 emp.zhangsan）')
    parser.add_argument('--init', action='store_true', help='初始化运行时目录')
    parser.add_argument('--status', action='store_true', help='查看状态')
    parser.add_argument('--stop', action='store_true', help='停止进程')
    args = parser.parse_args()

    # 显式传 agent_id，避免 RuntimeConfig 误读其他 argv
    config = RuntimeConfig(agent_id=args.agent_id)

    if args.init:
        return cmd_init(config)
    if args.status:
        return cmd_status(config)
    if args.stop:
        return cmd_stop(config)
    return cmd_run(config)


if __name__ == '__main__':
    sys.exit(main())
